// Dutch national flag: 0s, 1s and 2s in a single pass.
void sortColors(std::vector<int>& a) {
    int low = 0, mid = 0, high = (int)a.size() - 1;

    while (mid <= high) {
        if (a[mid] == 0) {
            std::swap(a[low++], a[mid++]);
        } else if (a[mid] == 2) {
            std::swap(a[mid], a[high--]);
            // mid does NOT advance: the value swapped in is unexamined.
        } else {
            mid++;
        }
    }
}

